const paths={open:'M3 6h6l2 2h10v11H3z M3 10h18',save:'M4 3h13l3 3v15H4z M8 3v6h8V3 M8 21v-8h8v8',export:'M12 15V3 M8 7l4-4 4 4 M4 13v7h16v-7',plus:'M12 5v14 M5 12h14',tape:'M3 6h18v13H3z M7 10a2 2 0 1 0 .01 0 M17 10a2 2 0 1 0 .01 0 M8 19l2-4h4l2 4',qd:'M4 3h16v18H4z M8 3v6h8V3 M8 21v-7h8v7',disk:'M12 3a9 9 0 1 0 .01 0 M12 9a3 3 0 1 0 .01 0 M12 3v3 M21 12h-3',audio:'M3 10v4 M7 6v12 M11 3v18 M15 7v10 M19 5v14',record:'M12 4a8 8 0 1 0 .01 0 M9 9h6v6H9z',check:'M5 12l4 4L19 6',info:'M12 3a9 9 0 1 0 .01 0 M12 10v7 M12 7v.1',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',search:'M10 3a7 7 0 1 0 .01 0 M15 15l6 6',inspect:'M3 4h18v16H3z M15 4v16 M18 8h.1 M18 12h.1',fit:'M4 9V4h5 M15 4h5v5 M20 15v5h-5 M9 20H4v-5',hex:'M8 4L3 12l5 8 M16 4l5 8-5 8 M14 3l-4 18',warning:'M12 3L2 21h20z M12 9v5 M12 17v.1',clock:'M12 3a9 9 0 1 0 .01 0 M12 7v6l4 2',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',stop:'M6 6h12v12H6z',play:'M8 4l12 8-12 8z',table:'M3 4h18v16H3z M3 9h18 M3 14h18 M9 4v16'};
const I=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.info}"/></svg>`;
const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const B=(text,action,ico='',cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ico?I(ico):''}${text}</button>`;
const badge=(text,kind='healthy')=>`<span class="badge ${kind}">${I(kind==='healthy'?'check':kind==='warning'?'warning':kind==='readonly'?'lock':'info')}${text}</span>`;
const views={tape:{title:'Tape workspace',file:'barbarian2.mzt',kind:'MZT · 6 records',icon:'tape'},qd:{title:'QuickDisk workspace',file:'flappy.qd',kind:'QD · HxC physical',icon:'qd'},disk:{title:'Disk workspace',file:'CPM41-work.dsk',kind:'Extended DSK · CP/M',icon:'disk'},audio:{title:'Audio analysis',file:'tape-side-a.wav',kind:'WAV · 48 kHz · Stereo',icon:'audio'},recorder:{title:'Tape recorder',file:'Recorder',kind:'Input stopped',icon:'record'}};
const model={view:new URLSearchParams(location.search).get('view')||'tape',selected:{tape:1,qd:0,disk:2,audio:1},modified:{tape:true,qd:false,disk:false},names:{},zooms:{},scrolls:{},tabs:{},inspector:false,sector:{c:8,r:3},sectorOwner:'FLAPPY.COM',recorder:'idle',samePassage:false,repair:false,notice:'Design review · all values and files are illustrative.'};
if(!views[model.view])model.view='tape';
