const diskRows=[['CCP.COM','0','6.0 KiB','SYS','12','Verified'],['BASIC.COM','0','18.0 KiB','—','36','Verified'],['FLAPPY.COM','0','23.8 KiB','—','48','Verified'],['README.TXT','0','1.5 KiB','—','3','Verified']];
