function table(headers,rows,key){return `<div class="table-scroll"><table class="table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr tabindex="0" data-row="${i}" data-table="${key}" aria-selected="${model.selected[key]===i}">${r.map((c,n)=>`<td class="${n===0?'name':''} ${/^0x|KiB| s$/.test(c)?'mono':''}">${['Verified','Modified'].includes(c)?badge(c,c==='Modified'?'modified':'healthy'):c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function panel(title,body,right='',foot=''){return `<section class="panel"><header class="panel-head"><h3>${title}</h3><div class="right">${right}</div></header>${body}${foot?`<footer class="panel-foot">${foot}</footer>`:''}</section>`;}
function dl(pairs){return `<dl>${pairs.map(([k,v])=>`<dt>${k}</dt><dd ${/^0x/.test(v)?'class="mono"':''}>${v}</dd>`).join('')}</dl>`;}
function inspector(title,name,pairs,extra=''){return `<aside class="inspector ${model.inspector?'open':''}" aria-label="Selection inspector"><section class="panel"><header class="panel-head"><h3>${title}</h3>${I('inspect')}</header><div class="detail-name">${name}</div>${dl(pairs)}${extra}</section></aside>`;}
function graphToolbar(channels=true){return `<div class="graph-toolbar">${B('−','zoom-out','','small','aria-label="Zoom out"')}${B('+','zoom-in','','small','aria-label="Zoom in"')}${B('Fit all','fit','fit','small '+(!(model.zooms[model.view]>1)?'active':''),'aria-pressed="'+(!(model.zooms[model.view]>1))+'"')}${B('Fit selection','fit-selection','','small')}<span class="toolbar-label" data-zoom-label>${model.zooms[model.view]>1?'Zoom '+model.zooms[model.view].toFixed(1)+'×':'Full range'}</span>${channels?'<div class="legend"><span><i class="swatch line" style="background:var(--wave-l)"></i>Left</span><span><i class="swatch line" style="background:var(--wave-r)"></i>Right</span></div>':''}</div>`;}
function waveform(height=130,record=false){let lines='';for(let i=0;i<350;i++){const x=42+i*1.83;let amp=(Math.sin(i*.043)**2*.7+.2)*(Math.sin(i*1.81)*.32+.68);if(i<28||i>320)amp*=.16;const a=amp*height*.2;lines+=`<path d="M${x.toFixed(1)} ${(height*.3-a).toFixed(1)}v${(a*2).toFixed(1)}" class="wave-left"/><path d="M${x.toFixed(1)} ${(height*.73-a*.86).toFixed(1)}v${(a*1.72).toFixed(1)}" class="wave-right"/>`;}
const selected=regionRows[model.selected.audio]||regionRows[1];const sx=record?190:40+parseFloat(selected[3])/12*650;const sw=record?235:(parseFloat(selected[4])-parseFloat(selected[3]))/12*650;return `<div class="chart"><svg viewBox="0 0 710 ${height+30}" role="img" aria-label="Illustrative stereo waveform; selection also has a text description." tabindex="0" data-graph="wave"><title>Model waveform. Wheel zoom; drag pan; Shift+drag select. No PCM is processed.</title><defs><clipPath id="wave-clip"><rect x="40" y="8" width="650" height="${height-6}"/></clipPath></defs>${[0,1,2,3,4].map(i=>`<line class="grid" x1="40" x2="690" y1="${12+i*(height-20)/4}" y2="${12+i*(height-20)/4}"/>`).join('')}${[0,1,2,3,4,5,6].map(i=>`<line class="grid" x1="${40+i*108}" x2="${40+i*108}" y1="8" y2="${height}"/><text x="${40+i*108}" y="${height+19}" text-anchor="middle">${(record?i*.2:i*2).toFixed(record?1:0)}</text>`).join('')}<g clip-path="url(#wave-clip)"><rect class="selection" x="${sx}" y="8" width="${sw}" height="${height-8}"/><g stroke-width="1" fill="none">${lines}</g><path class="selection-line" d="M${sx} 8v${height-8} M${sx+sw} 8v${height-8}"/></g><text x="11" y="${height*.3}">L</text><text x="11" y="${height*.73}">R</text><text x="700" y="${height+19}">s</text></svg></div>`;}
function histogram(){let bars='';for(let i=0;i<70;i++){const h=13+Math.exp(-Math.pow((i-20)/4.5,2))*83+Math.exp(-Math.pow((i-47)/5.5,2))*63;bars+=`<rect x="${39+i*4}" y="${126-h}" width="2.9" height="${h}" fill="${i<33?'var(--pulse-sh)':'var(--pulse-lh)'}"/>`;}return `<div class="chart"><svg viewBox="0 0 350 166" role="img" aria-label="Illustrative pulse histogram; schematic guides are not decoder timing."><title>Model only; production references come from the single shared catalog.</title>${[40,80,120].map(y=>`<line class="grid" x1="35" x2="330" y1="${y}" y2="${y}"/>`).join('')}${bars}<path d="M119 20v110 M231 20v110" stroke="var(--wave-r)" stroke-width="1.2" stroke-dasharray="4 4"/>${[0,1,2,3].map(i=>`<text x="${35+i*98}" y="150" text-anchor="middle">${i*250}</text>`).join('')}<text x="325" y="163">µs</text><text x="5" y="22">N</text></svg></div>`;}
function spectrum(){let p='';for(let i=0;i<140;i++){const y=112-69*Math.exp(-Math.pow((i-21)/4,2))-20*Math.exp(-Math.pow((i-62)/8,2))+Math.sin(i*3.7)*4;p+=(i?'L':'M')+(36+i*2.1).toFixed(1)+' '+y.toFixed(1)+' ';}return `<div class="chart"><svg viewBox="0 0 350 166" role="img" aria-label="Example FFT amplitude spectrum in dBFS, not PSD.">${[30,65,100,130].map((y,i)=>`<line class="grid" x1="35" x2="330" y1="${y}" y2="${y}"/><text x="1" y="${y+3}">${-i*30}</text>`).join('')}<path d="${p}" stroke="var(--wave-l)" stroke-width="1.5" fill="none"/><text x="35" y="150">0</text><text x="157" y="150">12</text><text x="290" y="150">24 kHz</text></svg></div>`;}
function tape(){const r=tapeRows[model.selected.tape];return {tabs:['Records','Metadata','Hex'],main:panel('Records',table(['Name','Type','Load','Execute','Size','Tape profile','State'],tapeRows,'tape'),`<label class="filter">${I('search')}<input aria-label="Filter records" placeholder="Filter records…" data-filter="tape"></label>`,`<span>6 records · 99.9 KiB payload</span><span>Order preserved on export</span>`)+panel('Selected record',`<div class="panel-body"><div class="label-row"><strong>${E(r[0])}</strong>${badge('Original header preserved','readonly')}</div><div class="legend"><span>${I('tape')} Tape profile</span><span>${r[5]}</span></div><div class="qd-strip"><span style="flex:2">ROM header</span><span class="gap" style="flex:.6">gap</span><span style="flex:1.2">loader</span><span class="payload focus" style="flex:6">Program payload</span><span class="gap" style="flex:.4">end</span></div><div class="note">This profile has separate header, loader and payload stages. Save changes the document; Export creates a separate output.</div></div>`,'','<span>Model data · structure illustration</span><span>Header → loader → payload</span>'),side:inspector('Record inspector',E(r[0]),[['Record',`${model.selected.tape+1} of 6`],['Type',r[1]],['Load address',r[2]],['Execute address',r[3]],['Payload',r[4]],['Source compression','Not detected']],`<section><h3>Tape profile</h3><p>${r[5]}<br>Separate header and loader context.</p>${B('Edit metadata…','metadata','settings')}</section><section><h3>Document state</h3><p>Save binds this document. Export creates a separate artifact.</p>${badge(model.modified.tape?'Modified':'Saved',model.modified.tape?'modified':'healthy')}</section>`) };}
function quickDisk(){const rows=[['FLAPPY ver 1.0A','OBJ','23.8 KiB','2','Verified'],['Highway Ver 1.02','OBJ','17.7 KiB','2','Verified'],['README','ASC','1.2 KiB','2','Verified']];return {tabs:['Directory','Physical map','Hex'],main:panel('Directory',table(['Name','Type','Size','Frames','State'],rows,'qd'),B('Import…','import','plus','small'),'<span>SHARP MZ · 3 logical files</span><span>Original image preserved</span>')+panel('Physical QuickDisk map',`${graphToolbar(false)}<div class="panel-body"><div class="label-row"><strong>Physical stream → selected file</strong><span class="muted mono">0x000000 … 0x00FFFF</span></div>${[0,1,2].map(n=>`<div class="qd-strip"><span style="flex:1">sync</span><span style="flex:2">header ${n+1}</span><span class="gap" style="flex:.6">gap</span><span class="payload ${model.selected.qd===n?'focus':''}" style="flex:7">${rows[n][0]}</span><span style="flex:1">CRC</span></div>`).join('')}<div class="legend"><span><i class="swatch"></i>Selection</span><span>Framing</span><span>Gap / unassigned</span></div></div>`,'','<span>Logical selection ↔ physical byte range</span><span>Illustrative map</span>'),side:inspector('File inspector',E(rows[model.selected.qd][0]),[['Container','HxC physical QD'],['Host','SHARP MZ'],['Logical payload',rows[model.selected.qd][2]],['Selected unit','Decoded program'],['CRC evidence','Example: valid']],`<section><h3>View and export</h3><p>Decoded bytes and the original physical stream remain distinct.</p>${B('Open hex view…','hex','hex')}</section><section>${badge('Healthy')}<p>Other hosts retain their current inspection and write limitations.</p></section>`) };}
function diskMap(){let cells='<div></div>'+Array.from({length:20},(_,i)=>`<div class="track-index">${i*2}</div>`).join('');for(let r=0;r<9;r++){cells+=`<div class="track-label">${r+1}</div>`;for(let c=0;c<20;c++){const kind=c===0?'system':c===1&&r<4?'directory':c>12||(c>8&&r>4)?'free':'used';const sel=c*2===model.sector.c&&r+1===model.sector.r;cells+=`<button class="sector-block ${kind} ${sel?'selected':''}" data-action="sector" title="Cylinder ${c*2}, side 0, sector ${r+1}; ${kind}" aria-label="Select cylinder ${c*2}, side 0, sector ${r+1}; ${kind}" data-sector="${c*2}:${r+1}" aria-pressed="${sel}" tabindex="${sel?0:-1}"></button>`;}}return `<div class="disk-map"><div class="disk-grid">${cells}</div></div><div class="legend disk-legend"><span><i class="swatch" style="background:var(--disk-system)"></i>System</span><span><i class="swatch" style="background:var(--disk-directory)"></i>Directory</span><span><i class="swatch" style="background:var(--disk-file)"></i>File data</span><span><i class="swatch" style="background:var(--readonly-bg)"></i>Free</span></div>`;}
function disk(){return {tabs:['Disk map','Files','Structure','Hex','Diagnostics'],main:panel('Disk map',graphToolbar(false)+diskMap(),'<span class="muted" style="font-size:11px">Cylinder → · side 0</span>','<span>40 cylinders × 2 sides · 9 sectors / track</span><span>Illustrative sampled map</span>')+panel('Files on this disk',table(['Name','User','Size','Attributes','Blocks','State'],diskRows,'disk'),B('Filesystem…','filesystem','settings','small'),'<span>4 files shown · sample layout</span><span>Allocation ≠ physical status</span>'),side:inspector('Sector inspector',`C${String(model.sector.c).padStart(2,'0')} · H0 · R${String(model.sector.r).padStart(2,'0')}`,[['CHRN',`0x${model.sector.c.toString(16).toUpperCase().padStart(2,'0')} / 0x00 / 0x${model.sector.r.toString(16).toUpperCase().padStart(2,'0')} / 0x02`],['Stored bytes','512 B'],['ST1 / ST2','0x00 / 0x00'],['Owner',model.sectorOwner],['Filesystem','CP/M'],['State','Example: healthy']],`<section><h3>Selected bytes</h3><pre class="hex"><span class="offset">0x0000</span> <span class="hl">C3 08 12</span> 00 00 00
<span class="offset">0x0006</span> 00 00 46 4C 41 50
<span class="offset">0x000C</span> 50 59 00 00 00 00</pre><div style="height:10px"></div>${B('Edit sector…','hex','hex')}</section><section><h3>Container repair</h3><p>Healthy disks open directly. Repairs preserve the original.</p>${B('Preview repair workflow…','repair','settings')}</section>`) };}
function audio(){const r=regionRows[model.selected.audio];return {tabs:['Signal & regions','Pulse analysis','Recovery','Statistics'],main:panel('Waveform',graphToolbar()+waveform(105)+`<div class="chart-caption"><span class="mono">Selection [${Math.round(parseFloat(r[3])*48000).toLocaleString('en-US')}, ${Math.round(parseFloat(r[4])*48000).toLocaleString('en-US')}) frames</span><span>48 kHz · amplitude FS</span></div>`,B('Analyze selection…','recover','search','small'))+panel('Records and regions',table(['Record','Name','Region','Start','End','State'],regionRows,'audio'),B('Export region…','export','export','small'))+`<div class="split-charts">${panel('Pulse histogram · N',histogram(),'<span class="muted" style="font-size:11px">Example distribution</span>')}${panel('Spectrum · dBFS',spectrum(),'<span class="muted" style="font-size:11px">Hann · N=4096</span>')}</div>`,side:inspector('Selection inspector',`Record ${r[0]} · ${r[2].toLowerCase()}`,[['Interval',`[${parseFloat(r[3])}, ${parseFloat(r[4])}) s`],['Frames',String(Math.round((parseFloat(r[4])-parseFloat(r[3]))*48000))],['Channels','Stereo · L / R'],['Source','Unchanged WAV'],['Detector','Example: adaptive'],['Checksum','Example: valid']],`<section><h3>Pulse references</h3><label class="field">Profile<select aria-label="Pulse reference profile"><option>MZ-800 ROM</option><option>NORMAL 1:3</option><option>IC 1:3</option><option>TC 1:2</option><option>User reference…</option></select></label><p>Guides come from the shared catalog. Visual overlays do not define decoder timing.</p>${B('Reference details…','reference','info')}</section><section><h3>Source protection</h3><p>Analysis and region exports preserve the source audio.</p>${badge('Read-only source','readonly')}</section>`) };}
function dial(channel,value,rotation){return `<div class="dial"><div class="label-row"><strong>${channel}</strong><span class="muted">Edge change</span></div><svg viewBox="0 0 180 74" role="img" aria-label="Example ${channel} relative edge change ${value} microseconds"><path d="M22 66 A68 60 0 0 1 158 66" fill="none" stroke="var(--border)" stroke-width="7"/><path d="M90 64L90 12" stroke="var(--${channel==='Left'?'wave-l':'wave-r'})" stroke-width="2" transform="rotate(${rotation} 90 64)"/><circle cx="90" cy="64" r="4" fill="var(--text)"/><text x="15" y="73" fill="var(--muted)" font-size="9">−10</text><text x="154" y="73" fill="var(--muted)" font-size="9">+10</text><text x="87" y="8" fill="var(--muted)" font-size="9">0</text></svg><div class="dial-value mono">${value} <span class="muted" style="font-size:11px">µs</span></div><div class="dial-caption">Relative to this tape's manual zero</div></div>`;}
function recorder(){return {tabs:['Overview','Live signal','Head alignment','Live pulses','Recordings','Diagnostics'],main:panel('Input and archive',`<details class="input-details"><summary>Synthetic demo · requested 48 kHz stereo PCM24 · native archive <span>Input settings</span></summary><div class="settings-grid"><label class="field">Source<select aria-label="Input source" data-recorder-setting><option>Synthetic demo · no device</option><option disabled>Windows WASAPI · production only</option><option disabled>Linux / macOS · backend pending</option></select></label><label class="field">Access mode<select aria-label="Access mode" data-recorder-setting><option>Shared</option><option>Exclusive · Windows only</option></select></label><label class="field">Requested format<select aria-label="Requested sample format" data-recorder-setting><option>48 000 Hz · stereo · PCM24</option><option>96 000 Hz · stereo · PCM24</option></select></label><label class="field">Archive mode<select aria-label="Archive policy" data-recorder-setting><option>Preserve native format</option><option>Explicit PCM24 conversion</option></select></label><label class="field wide">Destination<span class="inline-value mono">Recordings / tape-side-a.wav</span></label></div></details><div class="recorder-bar">${badge(model.recorder==='idle'?'Input stopped':model.recorder==='monitoring'?'Demo monitor':'Demo recording',model.recorder==='recording'?'error':model.recorder==='idle'?'readonly':'healthy')}<span class="muted" style="font-size:11px">Actual format: ${model.recorder==='idle'?'not negotiated':'simulated PCM24'}</span><span class="recorder-state">${I('lock')} Archive ≠ preview</span></div>`)+'<div class="recorder-overview">'+panel('Head alignment · example snapshot',`<div class="head-grid">${dial('Left','+0.4',4)}${dial('Right','−0.3',-3)}</div><div class="panel-body" style="padding-top:0"><div class="note">Relative evidence for the same passage. No absolute mechanical angle or combined quality score.</div><div style="height:12px"></div><label class="checkline"><input type="checkbox" id="same-passage" ${model.samePassage?'checked':''}> Same passage replayed; gain, EQ and input chain unchanged</label></div><div class="panel-foot"><span data-comparison-status>${model.samePassage?'Example A/B comparison available':'A/B needs same-passage confirmation'}</span><span>${B('Snapshot A','snapshot-a','','small')}${B('Snapshot B','snapshot-b','','small')}</span></div>`,'<span class="record-preview-label">Illustrative · no measurement running</span>')+panel('Signal preview · example snapshot',graphToolbar()+waveform(105,true)+spectrum(),'','<span>Display gain / channel never changes archived PCM</span>')+'</div>',side:inspector('Session inspector',model.recorder==='idle'?'Ready to start':model.recorder==='monitoring'?'Monitoring · demo':'Recording · demo',[['Input state',model.recorder==='idle'?'Stopped':'Simulated'],['Archive integrity',model.recorder==='recording'?'Demo only':'Not recorded'],['Archive loss','0 frames · example'],['Preview loss','0 frames · example'],['Timestamp origin','Not started']],`<section><h3>Safe lifecycle</h3><p>Monitor creates no archive. Record requires an explicit action. Stop waits for finalization.</p>${B('View close policy…','close-policy','info')}</section><section><h3>Recorded output</h3><p>WAV + JSON / SHA-256; segments form one recording.</p>${B('Open recordings…','recordings','open')}</section>`) };}
const compose=()=>({tape,qd:quickDisk,disk,audio,recorder}[model.view])();
function render(){const v=views[model.view],file=E(model.names[model.view]||v.file),body=compose(),canSave=['tape','qd','disk'].includes(model.view),active=model.recorder!=='idle';document.title=`MZTools · ${v.title} · F2 review`;document.getElementById('app').innerHTML=`<div class="app" data-view="${model.view}"><header class="app-header"><div class="left"><div class="brand"><span class="brand-mark">MZ</span>MZTools</div><nav class="menubar" aria-label="Application menu">${B('File','file','','quiet')}${B('Edit','edit','','quiet')}${B('View','view-menu','','quiet')}${B('Tools','tools','','quiet')}</nav></div><div class="review-label"><span class="pill">F2 · UI STUDY</span><span class="long">Model data · no file or device access</span>${B('Review notes','review','info','quiet small')}</div></header><div class="commandbar" role="toolbar" aria-label="Document commands">${B('Open…','open','open')}${B('Save','save','save','',!canSave||!model.modified[model.view]||(model.view==='disk'&&model.repair&&!model.names.disk)?'disabled':'')}${B('Save As…','save-as','','',!canSave?'disabled':'')}<span class="separator"></span>${B('Import…','import','plus','secondary-command',!canSave?'disabled':'')}${B('Export…','export','export')}<span class="spacer"></span>${model.view==='recorder'?`${B('Monitor','monitor','play','',active?'disabled':'')}${B('Record','record','','primary',model.recorder==='recording'?'disabled':'')}${B('Stop / finalize','stop','stop','',!active?'disabled':'')}`:`<span class="command-hint">${I('clock')}Changes stay in memory until Save</span>`}</div><nav class="docbar" aria-label="Open documents">${Object.entries(views).map(([key,d])=>`<button class="doc-tab" data-view="${key}" ${key===model.view?'aria-current="page"':''} title="Activate ${E(d.file)}">${I(d.icon)}${E((model.names[key]||d.file)+(model.modified[key]?" *":""))}${model.modified[key]?'<span class="dirty-dot" aria-label="Modified"></span>':''}${key==='recorder'&&active?'<span class="record-symbol" aria-label="Demo active"></span>':''}</button>`).join('')}</nav><div class="body"><aside class="sidebar"><div><div class="eyebrow nav-title">WORKSPACES</div><nav class="nav-group" aria-label="Workspaces">${Object.entries({tape:'Tape',qd:'QuickDisk',disk:'Disks / HFE',audio:'Audio analysis',recorder:'Recorder'}).map(([key,label])=>`<button class="nav-item" data-view="${key}" title="${label}" aria-label="${label}" ${key===model.view?'aria-current="page"':''}>${I(views[key].icon)}<span class="nav-label">${label}</span><span class="count">${key==='recorder'?'':1}</span></button>`).join('')}</nav></div><div><div class="eyebrow nav-title">UTILITIES</div>${B('<span class="nav-label">Batch process</span>','batch','table','nav-item','aria-label="Batch process"')}${B('<span class="nav-label">Reports</span>','reports','export','nav-item','aria-label="Reports"')}</div><div class="side-note"><strong>Selection context</strong><p>Files, maps and details share the same selection.</p></div><div class="side-link">${I('settings')}<span>Preferences</span></div></aside><main class="workspace" id="workspace"><header class="workspace-title"><div><div class="title-line"><h1>${v.title}</h1>${model.modified[model.view]?badge('Modified','modified'):model.view==='audio'?badge('Read-only source','readonly'):model.view==='recorder'?badge('Demo preview','readonly'):badge('Healthy')}</div><p>${file} · ${v.kind}</p></div><div class="workspace-tools">${model.view==='disk'?B('Disk actions…','disk-actions','settings','small'):model.view==='tape'?B('Add records…','import','plus','small'):''}${B('Inspector','inspector','inspect','small',`aria-pressed="${model.inspector}"`)}</div></header><div class="subtabs" role="tablist" aria-label="${v.title} views">${body.tabs.map((t,i)=>`<button role="tab" data-tab="${i}" aria-selected="${(model.tabs[model.view]||0)===i}">${t}</button>`).join('')}</div><div class="work-grid"><div class="work-main">${body.main}</div>${body.side}</div></main></div><footer class="statusbar"><div><span class="status-dot"></span><span id="status-message">${E(model.notice)}</span></div><div><span>${model.view==='recorder'?active?'Demo only · no audio acquired':'No device started':v.kind}</span><span>F2 draft</span></div></footer></div>`;
wire();const main=document.getElementById('workspace');main.scrollTop=model.scrolls[model.view]||0;main.onscroll=()=>model.scrolls[model.view]=main.scrollTop;if(active)document.querySelectorAll('[data-recorder-setting]').forEach(el=>el.disabled=true);syncZoom();}
function notify(s){model.notice=s;const out=document.getElementById('status-message');if(out)out.textContent=s;document.getElementById('announcer').textContent=s;}
function showDialog(title,body,actions=[['Close','cancel']]){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').innerHTML=body;document.getElementById('dialog-actions').innerHTML=actions.map(([label,value,cls])=>`<button value="${value}" ${cls?`class="${cls}"`:''}>${label}</button>`).join('');const d=document.getElementById('review-dialog');d.onclose=null;d.returnValue='';d.showModal();return d;}
function explain(title,body){showDialog(title,`<p>${body}</p><div class="note">Local F2 review only. No real media is opened, saved or recorded.</div>`);}
function setView(view){model.view=view;render();}
function activateTab(i){model.tabs[model.view]=Number(i);document.querySelectorAll('[data-tab]').forEach(el=>el.setAttribute('aria-selected',String(Number(el.dataset.tab)===Number(i))));const panels=[...document.querySelectorAll('.work-main > .panel,.work-main > .split-charts')];if(i>0)panels[Math.min(i,panels.length-1)]?.scrollIntoView({block:'nearest'});notify(`${compose().tabs[i]} selected · section preview; complete feature views are defined in the parity map.`);}
function syncZoom(){const v=model.zooms[model.view]||1;document.querySelectorAll('[data-zoom-label]').forEach(el=>el.textContent=v===1?'Full range':`Zoom ${v.toFixed(1)}×`);document.querySelectorAll('[data-action="fit"]').forEach(el=>{el.classList.toggle('active',v===1);el.setAttribute('aria-pressed',String(v===1));});document.querySelectorAll('[data-graph="wave"] g[clip-path] > g').forEach(el=>el.setAttribute('transform',`translate(${-(v-1)*170} 0) scale(${v} 1)`));}
function zoom(f){model.zooms[model.view]=Math.max(1,Math.min(16,(model.zooms[model.view]||1)*f));syncZoom();notify((model.zooms[model.view]===1?'Fit all':`Preview zoom ${model.zooms[model.view].toFixed(1)}×`)+' · samples unchanged');}
const explanations={export:['Export separate artifact','Export preserves the active source and its modified state. Explicitly select records, decoded bytes, physical data, an audio region or a report. Format conversion belongs here, not in Save As.'],reference:['Pulse reference details','The view projects one shared catalog, including source, derivation and separate HIGH/LOW contexts. IC/NORMAL aliases with identical guides do not reset measurements. This prototype contains no historical timing table.'],recover:['Analyze selected audio','Choose a detector, channel/polarity and reference tests for the half-open frame selection. Preview checksums and candidates, then export explicitly. Source PCM stays unchanged.'], 'disk-actions':['Disk actions','Format, compare, normalize and container repair have a change preview. Filesystem repair is separate. Boot/system installation retains existing capability and verification gates.'],filesystem:['Filesystem actions','Copy, rename, properties, guided repair and defragmentation operate on one document and selection. Unsupported and read-only cases retain an explanation.'],hex:['Hex editor','Show physical addresses, bytes, pending edits and exact changed ranges. Apply updates the working document. Save remains separate. Closing pending edits asks before discarding them.'],metadata:['Record metadata','Edit representable Sharp names, header fields and supported profiles. Existing loader/compression restrictions remain. Apply marks the document modified; Cancel does not.'],import:['Import into active document','Preview selected content, ordering and collisions. Overwrite, rename and Cancel are explicit. Import changes the working document and does not silently save it.'],recordings:['Recordings','Show WAV segments, JSON integrity report, native/converted format and incomplete state. Analysis opens the complete segmented recording and never a growing live WAV for preview.'],batch:['Batch process','Preview operation, inputs, destination and collisions. Execution explicitly creates output files. Progress supports cancellation and per-file reports. Partial successful outputs remain clearly identified.'],reports:['Report viewer','Use shared property, issue and changed-range tables. Export TXT, CSV or JSON separately. Keep the diagnostic code, concrete impact and recovery action.'],file:['File menu','Open · Save · Save As · Import · Export · Close document. One command model drives menus, toolbar and keyboard. Recorder finalization is a separate session command.'],edit:['Edit menu','Rename (F2), selection and supported copy/paste share one command model. Undo/redo appears only where safely implemented or separately approved.'],'view-menu':['View menu','Show inspector, restore layout, Fit all and Fit selection. Keep viewport and selection between views. Native OS menu placement can differ; command meaning stays the same.'],tools:['Tools menu','Batch processing, MZF/M12 → COM, pulse catalog and recorder use common panels/dialogs. Preserve existing format and compression capabilities.'],review:['MZTools UI Design System · F2','Review the shared shell, components, selection, zoom and action wording. Documents and graphs are illustrative. Native screens, decoding, file I/O and capture belong to separately approved implementation phases.']};
function perform(action){if(explanations[action]){explain(...explanations[action]);return;}switch(action){
case 'inspector':model.inspector=!model.inspector;render();break;
case 'zoom-in':zoom(1.5);break;case 'zoom-out':zoom(1/1.5);break;case 'fit':model.zooms[model.view]=1;zoom(1);break;case 'fit-selection':zoom(2);break;
case 'save':if(model.view==='disk'&&model.repair&&!model.names.disk){notify('Original protected: Save As is required.');return;}if(model.modified[model.view]){model.modified[model.view]=false;render();notify('Review simulation: marked saved. No file was written.');}break;
case 'save-as':{const old=model.names[model.view]||views[model.view].file;const repaired=model.view==='disk'&&model.repair;const d=showDialog('Save As',`<p>Create a bound copy. The active document changes only after a successful verified write.</p>${repaired?'<div class="note warning">Repaired copy: the original, including file links, remains protected. Choose a distinct destination.</div>':''}<label>Destination name<input id="review-filename" value="${E(repaired?'CPM41-repaired.dsk':old)}" aria-label="Destination name"></label>`,[['Cancel','cancel'],['Simulate Save As','save','primary']]);d.onclose=()=>{if(d.returnValue==='save'){const n=document.getElementById('review-filename').value.trim();if(!n||(repaired&&n.toLowerCase()===views.disk.file.toLowerCase())){notify('No change: repair cannot overwrite the original.');return;}model.names[model.view]=n;model.modified[model.view]=false;render();notify('Review simulation: new document bound. No file written.');}};break;}
case 'repair':{const d=showDialog('Container repair preview',`<p>Example: restore a deterministic header field from complete track boundaries. No payload is invented.</p><div class="note warning"><strong>Original preserved.</strong> Apply changes the working copy. Save As must use a different destination.</div><table class="mini-table"><tr><th>Range</th><th>Change</th></tr><tr><td class="mono">0x0030</td><td>Illustrative header field</td></tr><tr><td>Sector payloads</td><td>Unchanged</td></tr></table><p>Container and filesystem repair are separate. Healthy disks open without this prompt.</p>`,[['Cancel','cancel'],['Apply to working copy','apply','primary']]);d.onclose=()=>{if(d.returnValue==='apply'){model.repair=true;model.modified.disk=true;render();notify('Repair applied to the model. Original protected; Save As required.');}};break;}
case 'monitor':model.recorder='monitoring';render();notify('Demo Monitor · no device, no archive.');break;
case 'record':model.recorder='recording';render();notify('Demo Record · no input, PCM, WAV or JSON created.');break;
case 'stop':model.recorder='idle';render();notify('Demo stopped / finalized. No real recording existed.');break;
case 'close-policy':{const d=showDialog('Close recorder?',`<p>The recorder has an independent lifetime. Closing the browser workspace does not discard it.</p><div class="note">Keep recording leaves capture running. Stop and finalize waits for the archive and integrity report before closing.</div>`,[['Keep recording','keep'],['Simulate stop and finalize','finalize','primary']]);d.onclose=()=>{if(d.returnValue==='finalize'){model.recorder='idle';render();notify('Demo recorder finalized; no real data existed.');}};break;}
case 'open':{const d=showDialog('Open document','<p>Production uses an explicit platform file picker. Cancel preserves the active document.</p><div class="note">Choose an example for this local review. No local file is read.</div>',[['Cancel','cancel'],['Tape example','tape'],['Disk example','disk','primary']]);d.onclose=()=>{if(views[d.returnValue])setView(d.returnValue);};break;}
case 'snapshot-a':case 'snapshot-b':notify(`Example ${action.endsWith('a')?'A':'B'} selected. ${model.samePassage?'Same passage confirmed.':'A/B remains unavailable until conditions are confirmed.'}`);break;
case 'sector':notify('Example sector selected · file and hex retain the same context.');break;
}}
function wire(){document.querySelectorAll('button[data-view]').forEach(el=>el.onclick=()=>setView(el.dataset.view));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{if(el.dataset.sector){const [c,r]=el.dataset.sector.split(':').map(Number);model.sector={c,r};const role=['free','directory','system'].find(k=>el.classList.contains(k));model.selected.disk=role?-1:Math.min(3,Math.floor(c/4));model.sectorOwner=role?({free:'Free / no file',directory:'Directory',system:'System area'}[role]):diskRows[model.selected.disk][0];render();document.querySelector('[data-sector="'+c+':'+r+'"]')?.focus({preventScroll:true});notify('Model sector selection synchronized with file and hex context.');}else perform(el.dataset.action);});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>activateTab(Number(el.dataset.tab)));document.querySelectorAll('[data-row]').forEach(el=>{const choose=()=>{model.selected[el.dataset.table]=Number(el.dataset.row);const key=model.view;if(key==='disk'){const [c,r]=[[0,1],[2,4],[8,3],[12,6]][model.selected.disk];model.sector={c,r};model.sectorOwner=diskRows[model.selected.disk][0];}render();document.querySelector(`[data-table="${key}"][data-row="${model.selected[key]}"]`)?.focus({preventScroll:true});};el.onclick=choose;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();choose();}else if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const n=Math.max(0,Math.min(el.parentElement.children.length-1,Number(el.dataset.row)+(e.key==='ArrowDown'?1:-1)));el.parentElement.children[n].click();}};});document.querySelectorAll('[data-filter]').forEach(el=>el.oninput=()=>{const q=el.value.toLowerCase();document.querySelectorAll(`[data-table="${el.dataset.filter}"]`).forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));});document.querySelectorAll('[data-graph]').forEach(el=>{el.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.5:1/1.5);},{passive:false});el.onkeydown=e=>{if(e.key==='Home'){e.preventDefault();model.zooms[model.view]=1;zoom(1);}if(['+','=','-'].includes(e.key)){e.preventDefault();zoom(e.key==='-'?1/1.5:1.5);}};let start=null;el.onpointerdown=e=>{start=e.clientX;el.setPointerCapture(e.pointerId);};el.onpointerup=e=>{if(start!==null&&Math.abs(e.clientX-start)>3)notify(e.shiftKey?'Model range selected · sample/frame bounds remain authoritative':'Preview pan · source data and manual zero unchanged');start=null;};});document.querySelectorAll('[data-sector]').forEach((cell,i)=>cell.onkeydown=e=>{const step={ArrowLeft:-1,ArrowRight:1,ArrowUp:-20,ArrowDown:20}[e.key];if(step){e.preventDefault();const cells=[...document.querySelectorAll('[data-sector]')];cells[Math.max(0,Math.min(cells.length-1,i+step))].click();}});const same=document.getElementById('same-passage');if(same)same.onchange=()=>{model.samePassage=same.checked;const status=document.querySelector('[data-comparison-status]');if(status)status.textContent=model.samePassage?'Example A/B comparison available':'A/B needs same-passage confirmation';notify(model.samePassage?'Same passage confirmed in the model.':'A/B disabled: unconfirmed passage conditions.');};document.querySelectorAll('button').forEach(el=>{if(!el.hasAttribute('title'))el.title=el.getAttribute('aria-label')||el.textContent.trim();if(el.disabled){const a=el.dataset.action;el.title=a==='save'?(model.view==='audio'?'Read-only audio source; use Export.':model.view==='disk'&&model.repair&&!model.names.disk?'Original protected; use Save As.':'No unsaved changes; Save As creates a copy.'):a==='save-as'?'This source/session is not a writable document.':a==='stop'?'Input is already stopped.':a==='import'?'The analysis source remains unchanged.':'Unavailable in the current session state.';}});}
document.addEventListener('keydown',e=>{if(document.getElementById('review-dialog').open)return;if((e.ctrlKey||e.metaKey)&&!e.altKey){if(e.key.toLowerCase()==='s'){e.preventDefault();const a=e.shiftKey?'save-as':'save';if(!document.querySelector(`[data-action="${a}"]`)?.disabled)perform(a);}if(e.key.toLowerCase()==='o'){e.preventDefault();perform('open');}}});
render();window.F2Review={model,setView,perform,zoom,render};
